#!/usr/bin/env python3
"""Deterministic generator for the 26 November 2026 news-image entry.

Reproduces entry.png -- a 1024x1024 world-news front page for 26 Nov 2026 --
deterministically from the embedded base64 payload, with no network access;
the output is byte-identical on every run.

The front page (1024x1024 JPEG) is embedded below as base64. Running
this program writes the exact same bytes to /output/entry.png every
time: no network, no randomness, no timestamps, stdlib only.
Re-running is safe: it overwrites the output file with identical bytes.
Verified locally on 26 November 2026: two runs write byte-identical
output (SHA-256 checked), and the image is 1024x1024, 192,733 bytes,
inside the 1 MiB limit.

Layout: a newspaper front page ("THE WORLD IN ONE IMAGE") with four
illustrated stories -- Trump's new tariffs on the EU, China and 12
others; the Houthis' claimed strike on Saudi Arabia's Ras Tanura
refinery as Brent tops $94; the FCC clearing SpaceX's million-satellite
"Starmind" data-centre constellation; and Ukraine's reported strike on
a Russian air base -- plus a footer of briefs. All facts were verified
against Reuters, BBC, the Wall Street Journal and France 24 on
26 November 2026; the panel illustrations are flat shapes drawn with
Pillow, so every word is exactly legible. The builder script that drew
the page is kept in work/build_frontpage.py.
"""

import base64
import hashlib
import os
import sys

# Base64 of the 1024x1024 front-page JPEG (192,733 bytes),
# split into 16,384-character lines.
IMAGE_B64 = (
    "",
)


EXPECTED_SHA256 = "51dc381ed28160a37c49a5bc6edbf3adcd7a90b83ebf7ec563b92eb106e90a45"
EXPECTED_SIZE = 192733


def main():
    data = base64.b64decode("".join(IMAGE_B64))
    if len(data) != EXPECTED_SIZE:
        sys.exit(f"embedded image size mismatch: {len(data)} bytes")
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        sys.exit("embedded image failed SHA-256 integrity check")
    out = os.environ.get("OUTPUT", "/output/entry.png")
    parent = os.path.dirname(out)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(out, "wb") as fh:
        fh.write(data)
    print(f"wrote {out} ({len(data)} bytes, sha256 {EXPECTED_SHA256[:16]}...)")


if __name__ == "__main__":
    main()
